package com.zeptopluse.controller; import com.zeptopluse.dto.CategoryResponse; import com.zeptopluse.service.CategoryService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.List; @RestController @RequestMapping("/api/v1/categories") @RequiredArgsConstructor public class CategoryController { private final CategoryService service; @GetMapping public List<CategoryResponse> list(){return service.list();} }